pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile lg;

    function setUp() public {
        c = new C();
        lg = new LogFile();
    }

    function testFuzz_property(address actor, uint256 amount, uint256 _lock) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e30);
        _lock = bound(_lock, 0, 1e12);

        // Adversarial helper used as the (buggy) Log target: its fallback reverts.
        BadLog bad = new BadLog();

        // Initialize config with a genuine LogFile.
        c.SetLogFile(address(lg));
        c.SetMinSum(0);
        c.Initialized();

        // Fund the actor and Put; in P, AddMessage goes to lg and succeeds.
        // In M (Log bound to msg.sender of SetLogFile would still be lg here)...
        // To expose M, SetLogFile must be called BY the adversarial party.
        vm.prank(address(bad));
        c.SetLogFile(address(lg));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(_lock) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after a properly initialized SetLogFile, any funded
        // actor's Put must succeed (logging reaches the real LogFile).
        assertTrue(ok);
    }
}

contract BadLog {
    fallback() external payable {
        revert();
    }
}

