contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint _val, uint _am) public payable {
        require(_val > 0 && _am > 0 && _am <= _val);
        require(address(this).balance >= 1 wei);
        c.SetLogFile(address(this));
        c.SetMinSum(_val);
        c.Initialized();
        c.Put{value: 1}(0);
        // In P, MinSum == _val and balance == 1, so Collect(_am) reverts (1 < _am).
        // In M, MinSum == 0, and since balance >= MinSum and balance >= _am fails for _am>0 ... Collect(_am) also reverts.
        // Instead: Collect(1)? P: balance(1) >= MinSum(_val>1?) reverts. M: MinSum=0, balance>=1, Collect(1) succeeds.
        bool reverted = false;
        // cannot nest state-changing call in try/if; use low-level check pattern is disallowed, so restructure:
        revert();
    }
}

